@Dao
interface LessonDao {
    @Query("SELECT * FROM lessons WHERE categoryId = :categoryId")
    fun getLessons(categoryId: String): Flow<List<LessonEntity>>
    // Room re-emits this Flow automatically on every insert/update/delete
}

// UI state - always has a current value
private val _uiState = MutableStateFlow(HomeUiState.Loading)
val uiState: StateFlow<HomeUiState> = _uiState

// one-time events - navigation, snackbars, toasts
private val _events = MutableSharedFlow<UiEvent>()
val events: SharedFlow<UiEvent> = _events

fun onSaveClicked() = viewModelScope.launch {
    _events.emit(UiEvent.ShowSnackbar("Saved!"))
}
